import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"雷风恒","description":"周易折中 - 雷风恒","frontmatter":{"title":"雷风恒","description":"周易折中 - 雷风恒"},"headers":[],"relativePath":"zh/classics/zhezhong/038.md","filePath":"zh/classics/zhezhong/038.md"}'),h={name:"zh/classics/zhezhong/038.md"};function p(n,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="雷风恒" tabindex="-1">雷风恒 <a class="header-anchor" href="#雷风恒" aria-label="Permalink to “雷风恒”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>恒序卦曰：夫妇之道，不可以不久也，故受之以恒。恒，久也。咸，夫妇之道，夫妇终身不变者也，故咸之后受之以恒也。咸，少男在少女之下，以男下女，是男女交感之义；恒，长男在长女之上，男尊女卑，夫妇居室之常道也。论交感之情，则少为亲切；论尊卑之序，则长当谨正。故兑艮为咸，而震巽为恒也。男在女上，男动于外，女顺于内，人理之常，故为恒也。又刚上柔下，雷风相与，巽而动，刚柔相应，皆恒之义也。</p><p>恒：亨，无咎，利贞，利有攸往</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>恒，常久也。为卦震刚在上，巽柔在下。震雷巽风，二物相与，巽顺震动，为巽而动。二体六爻阴阳相应，四者皆理之常，故为恒。其占为能久于其道，则亨而无咎。然又必利于守正则乃为得所常久之道，而利有所往也。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>恒者，常久也。恒之道可以亨通，恒而能亨，乃无咎也。恒而不可以亨，非可恒之道也，为有咎矣。如君子之恒于善，可恒之道也；小人恒于恶，失可恒之道也。恒所以能亨，由贞正也，故云“利贞”。夫所谓恒，谓可恒久之道，非守一隅而不知变也，故利于有往。惟其有往，故能恒也，一定则不能常矣。又常久之道，何往不利？</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱子语类云：恒是个一条物事，彻头彻尾，不是寻常字。古字作（缺失，可查古文字），其说象一只船两头靠岸，可见彻头彻尾。</p></li><li><p>徐氏几曰：恒有二义，有不易之恒，有不已之恒。利贞者，不易之恒也；利有攸往者，不已之恒也。合而言之，乃常道也。倚于一偏，则非道矣。</p></li><li><p>林氏希元曰：惟其不易，所以不已。</p></li></ul><p>象曰：雷风恒，君子以立不易方</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>君子观雷风相与成恒之象，以常久其德，自立于大中。常久之道，不变易其方所也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>吕氏大临曰：雷风虽若非常，其所以相与则恒。</p></li><li><p>胡氏炳文曰：雷风虽变而有不变者存。体雷风之变者，为我之不变者，善体雷风者也。</p></li></ul><p>说此象者，用“烈风雷雨弗迷”说震象者，用“迅雷风烈必变”，皆非也。雷风者，天地之变而不失其常也。立不易方者，君子之历万变而不失其常也。洊雷者，天地震动之气也；恐惧脩省者，君子震动之心也。</p><p>彖曰：恒久也，刚上而柔下，雷风相与，巽而动，刚柔皆应，恒</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>以卦体、卦象、卦德释卦名义，或以卦变言刚上柔下之义。曰恒自丰来，刚上居二，柔下居初也，亦通。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>恒者，长久之义也。卦才有此四者，成恒之义也。刚上而柔下，谓干之初上居于四，坤之初下居于初，刚爻上而柔爻下也。二爻易处，则成震巽，震上巽下，亦刚上而柔下也。刚处上而柔居下，乃恒道也。雷风相与，雷震则风发，二者相须交助其势，故云相与，乃其常也。巽而动，下巽顺，上震动，为以巽而动。天地造化恒久不已者，顺动而已。巽而动，常久之道也。动而不顺，岂能常也。刚柔皆应，一卦刚柔之爻皆相应。刚柔相应，理之常也。此四者，恒之道也。卦所以为恒也。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li>郑氏汝谐曰：咸与恒皆刚柔相应，咸不著其义，恒则曰刚柔皆应。咸无心，恒有位也。有位而刚柔相应，其理也；无心而刚柔相应，其私也。能识时义之变易，斯可言易矣。</li></ul><p>恒亨无咎，利贞，久于其道也；天地之道，恒久而不已也</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>恒固能亨且无咎矣，然必利于正，乃为久于其道。不正，则久非其道矣。天地之道，所以常久，亦以正而已矣。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>恒之道，可致亨而无过咎，但所恒宜得其正，失正则非可恒之道也。故曰“久于其道”，其道可恒之正道也。不恒其德与恒于不正，皆不能亨而有咎也。天地之所以不已，盖有恒久之道，人能恒于可恒之道，则合天地之理也。</p><p>利有攸往，终则有始也</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>久于其道终也，利有攸往始也。动静相生，循环之理然，必静为主也。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>天下之理，未有不动而能恒者也。动则终而复始，所以恒而不穷。凡天地所生之物，虽山岳之坚厚，未有能不变者也。故恒非一定之谓也，一定则不能恒矣。唯随时变易，乃常道也。故云“利有攸往”，明理之如是，惧人之泥于常也。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱氏震曰：易穷则变，变则通，通则久。恒非一定而不变也，随时变易其恒不动，故利有攸往。</p></li><li><p>朱子语类云：恒非一定之谓，一定则不能恒矣。体之常，所以为用之变；用之变，乃所以为体之常。</p></li><li><p>赵氏汝梅曰：所贵于攸往者，谓事虽有终，我行不已，则终者复有始，所以体天地之道也。</p></li></ul><p>日月得天而能久照，四时变化而能久成，圣人久于其道而天下化成，观其所恒而天地万物之情可见矣</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>极言恒久之道。</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>此极言常理。日月阴阳之精气耳，唯其顺天之道，往来盈缩，故能久照而不已，得天顺天理也。四时阴阳之气耳，往来变化生成万物，亦以得天故常久不已。圣人以常久之道行之有常，而天下化之以成羙俗也。观其所恒，谓观日月之久照，四时之久成，圣人之道所以能常久之理，观此则天地万物之情理可见矣。天地常久之道，天下常久之理，非知道者孰能识之？</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>苏氏轼曰：非其至情者，久则厌矣。</p></li><li><p>朱子语类云：物各有个情。有个人在此，决定是有个恻隠羞恶是非辞让之情性，只是个物事情，却多般或起或灭。然而头面却只一般，常常恁地，这便是“观其所恒而天地万物之情可见”之义。</p></li><li><p>龚氏焕曰：利贞久于其道，体常也；利有攸往，终则有始，尽变也。体常而后能尽变，尽变亦所以体常。天地万物所以常久者，以其能尽变也。</p></li><li><p>陈氏琛曰：即其恒久之理而观之，则天地万物之情可见矣。盖大气浑沦充塞，而太极为之纲维主张。气有参差，而理无不一。故天高地下，万物散殊，不特其声色貌象常久如此，而其德性功用亦亘万古而不易。少有变易，则为怪异不祥矣。此可见天地万物之情皆有恒也。</p></li></ul><h3 id="案释" tabindex="-1">案释 <a class="header-anchor" href="#案释" aria-label="Permalink to “案释”">​</a></h3><ul><li><p>利贞：云久于其道，则居所不迁之谓也。</p></li><li><p>利有攸往：云终则有始，则动静不穷之谓也。然两义并行，初不相悖。动静虽不穷，而所谓居所不迁者，未尝变也。然则天地之道，恒久不已与终则有始之义，一而已矣。下文天地日月即根此意而申明之。日月得天而能久照者，恒久不已也；四时变化而能久成者，终则有始也。日月为之体，四时为之用。四时者，日月之所为。合之皆天地之道也。圣人久于其道，如日月之得天而久照，化天下而成之，如四时之变化而久成。此恒道之大者也。推而广之，则凡在天地之闲者，其情皆可见。</p></li></ul><p>初六：浚恒，贞凶，无攸利</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>初与四为正应，理之常也。然初居下而在初，未可以深有所求。四震体而阳性，上而不下，又为二三所隔，应初之意异乎常矣。初之柔暗，不能度势，又以阴居巽下为巽之主，其性务入，故深以常理求之，浚恒之象也。占者如此，则虽正亦凶，而无所利矣。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>初居下而四为正应，柔暗之人能守常而不能度势。四震体而阳性，以刚居高，志上而不下，又为二三所隔，应初之志异乎常矣。而初乃求望之深，是知常而不知变也。浚，深之也。浚恒，谓求恒之深也。守常而不度势，求望于上之深，坚固守此，凶之道也。泥常如此，无所往而利矣。世之责望故素而致悔咎者，皆浚恒者也。志既上求之深，是不能恒安其处者也。柔微而不恒安其处，亦致凶之道。凡卦之初终，浅与深、微与盛之地也，在下而求深，亦不知时矣。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>陆氏希声曰：常之为义，贵久于其道，日以浸深。初为常始，宜以渐为常，而体巽性躁，遽求深入，是失久于其道之义，不可以为常，故贞凶。</p></li><li><p>胡氏瑗曰：天下之事，必皆有渐，在乎积日累久而后能成其功。是故为学既久，则道业可成，圣贤可到；为治既久，则教化可行，尧舜可至。若是之类，莫不由积日累久而后至，固非骤而及也。初六居下卦之初，为事之始，责其长久之道、永远之效，是犹为学之始，欲亟至于周孔；为治之始，欲化及于尧舜。不能积久其事而求常道之深，故于贞正之道见其凶也。无攸利者，以此而往，必无所利。孔子曰：“欲速则不达”，是也。</p></li><li><p>王氏宗传曰：初，巽之主也，当恒之初而以深入为恒，故曰浚恒。犹之造事也，未尝有一日之劳而遽求其事成；犹之为学也，未尝有一日之功而遽求其造道。夫造事而欲其有所成，为学而欲其有所造，固所当然。然望之太深，责之太遽，俱不免于无成而已，故凶而无攸利也。</p></li><li><p>王氏申子曰：恒久也，天下可久之事，岂一朝夕所能致者？初六质柔而志刚，质柔故昧于远见，志刚故欲速不达。处恒之初，是方为可久之计者，而遽焉求深，故曰浚恒。非急暴而不能恒，则必苟且而不可恒矣。贞固守此以为恒，取凶之道也，何所利哉？</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>此爻义陆氏、胡氏、二王氏俱与传义异，于卦义尤为精切，可从。盖凡事渐则能久，不渐则不能久矣。孟子所谓“其进锐者，其退速”也。</p><p>象曰：浚恒之凶，始求深也</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>居恒之始而求望于上之深，是知常而不知度势之甚也，所以凶。阴暗不得恒之宜也。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱氏震曰：初居巽下，以深入为恒；上居震极，以震动为恒。在始而求深，在上而好动，皆凶道也。</p></li><li><p>郭氏雍曰：进道有渐而后可久。在恒之初，浚而深求，非其道也。</p></li><li><p>王氏申子曰：可恒之道，以久而成。始而求深，是施诸己则欲速不达，施诸人则责之太遽者也，故凶。</p></li><li><p>苏氏浚曰：凡人用功之始，立志太锐，取效太急，便有欲速助长之病。故曰“始求深”，孟子言“深造必以道”，正是此意。</p></li></ul><p>九二：悔亡</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>以阳居阴，本当有悔，以其久中，故得亡也。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>在恒之义，居得其正则常道也。九阳爻居阴位，非常理也。处非其常，本当有悔。而九二以中德而应于五，五复居中以中而应中，其处与动皆得中也。是能恒久于中，也能恒久于中，则不失正矣。中重于正，中则正矣，正不必中也。九二以刚中之德而应于中德之胜，也足以亡其悔矣。人能识重轻之势，则可以言易矣。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li>程氏迥曰：大壮九二、解初六及此爻，皆不著其所以然，盖以爻明之也。</li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>恒者，常也，中则常矣。卦惟此爻以刚居中，大壮之壮戒于太过，而四阳爻惟二得中。解利西南，贵处后也，而卦惟初六为最后。此皆合乎卦义而甚明者，故直系以吉占，而辞可略也。</p><p>象曰：九二悔亡，能久中也</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>所以得悔亡者，由其能恒久于中也。人能恒久于中，岂止亡其悔，德之善也。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏炳文曰：九二独提“能久中”，诸爻不中，故不久，可见。</li></ul><p>九三：不恒其德，或承之羞，贞吝</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>位虽得正，然过刚不中，志从于上，不能久于其所，故为“不恒其德，或承之羞”之象。或者不知其何人之辞，“承奉”也，言人皆得奉而进之，不知其所自来也。“贞吝”者，正而不恒，为可羞吝，申戒占者之辞。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>三阳爻居阳位，处得其位，是其常处也。乃志从于上六，不惟阴阳相应，风复从雷，于恒处而不处，不恒之人也。其徳不恒，则羞辱或承之矣。“或承之”谓有时而至也。“贞吝”，固守不恒以为恒，岂不可羞吝乎？</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>苏氏轼曰：咸、恒无完爻，以中者用之可以悔亡，以不中者用之无常之人也。故九三“不恒其徳”。</p></li><li><p>王氏申子曰：人之为徳，过乎中则不能恒。三过乎中矣，且以刚居刚而处巽之极，过刚则躁，巽则不果，是无恒者也。</p></li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>易所最重者中，故卦徳之不善者，过乎中则愈甚，睽、归妹之类是也。卦徳之善者，过乎中则不能守矣，复、中孚之类是也。况恒者，庸也，常也，惟中故庸。未有失其中而能常者也。九三之所以为“不恒”，振恒者以此。</p><p>象曰：不恒其德，无所容也</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>人既无恒，何所容处？当处之地既不能恒处，非其据岂能恒哉？是不恒之人无所容处其身也。案：此“无所容”与“离”四相似，皆谓德行无常度自若，无所容非人不容之也。</p><p>九四：田无禽</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>以阳居阴，久非其位，故为此象。占者田无所获，而凡事亦不得其所求也。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>以阳居阴，处非其位，处非其所，虽常何益？人之所为，得其道则久而成功，不得其道则虽久何益？故以田为喻，言九之居四，虽使恒久如田猎，而无禽兽之获，谓徒用力而无功也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏瑗曰：常久之道，必本于中正。九四以阳居阴，是不正也；位不及中，是不中也。不中不正，不常之人也。以不常之人为治，则教化不能行，抚民则膏泽不能下，是犹田猎而无禽可获也。</li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>浚恒者，如为学太锐而不以序，求治太速而不以渐也。田无禽者，如学不衷于圣而失其方，治不凖于王而乖其术也。如此，则虽久何益哉？韩愈与候生钓鱼之诗，即此“田无禽”之喻也。</p><p>象曰：乆非其位，安得禽也</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>处非其位，虽久何所得乎？以田为喻，故云“安得禽也”。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏弼曰：恒非其位，虽劳无获也。</li></ul><p>爻既以田为喻，则非处非其位也，乃所往者非其位耳。谓所动而施为者不得其方也。</p><p>六五：恒其德贞，妇人吉，夫子凶</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>以柔中而应刚中，常久不易，正而固矣。然乃妇人之道，非夫子之宜也，故其象占如此。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>五应于二，以阴柔而应阳刚，居中而所应又中。阴柔之正也，故恒久其德则为贞也。夫以顺从为恒者，妇人之道。在妇人则为贞，故吉。若丈夫而以顺从于人为恒，则失其刚阳之正，乃凶也。五君位而不以君道言者，如六五之义。在丈夫犹凶，况人君之道乎？在它卦，六居君位而应刚，未为失也。在恒，故不可耳。君道岂可以柔顺为恒也？</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱子语类：问：“恒其德贞，妇人吉，夫子凶。”徳指六五，谓常其柔顺之德，固贞矣。然此妇人之道，非夫子之义。 曰：固是如此，然须看得象占分明。六五有“恒其德贞”之象，占者若妇人则吉，夫子则凶。大抵看易，须知得象占分明。所谓吉凶者，非爻之能吉凶，爻有此象，而占者视其德而有吉凶耳。</p></li><li><p>问：“恒其德贞，妇人吉，夫子凶。”徳指六五，谓常其柔顺之德，固贞矣。然此妇人之道，非夫子之义。 曰：固是如此，然须看得象占分明。六五有“恒其德贞”之象，占者若妇人则吉，夫子则凶。大抵看易，须知得象占分明。所谓吉凶者，非爻之能吉凶，爻有此象，而占者视其德而有吉凶耳。</p></li><li><p>丘氏富国曰：二以阳居阴，五以阴居阳，皆位不当而得中者也。在二则悔亡，而五有“夫子凶”之戒者，盖二以刚中为常，而五以柔中为常也。以刚处常，能常者也；以柔为常，则是妇人之道，非夫子所尚。此六五所以有从妇之凶。</p></li></ul><p>象曰：妇人贞吉，从一而终也；夫子制义从妇，凶也</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>如五之从二，在妇人则为正而吉。妇人以从为正，以顺为德，当终守于从一。夫子则以义制者，从妇人之道则为凶也。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>项氏安世曰：九二以刚中为常，故悔亡。六五以柔中为恒，在二可也，在五则夫也、父也、君也，而可乎？妇人从夫则吉，夫子从妇则凶矣。</p></li><li><p>杨氏启新曰：爻辞只曰“妇人吉”，象传又添一“贞”字，明“恒其德”贞为妇人之贞也。</p></li></ul><p>上六：振恒，凶</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>振者，动之速也。上六居恒之极，处震之终。恒极则不常，震终则过动。又阴柔不能固守，居上非其所安，故有“振恒”之象，而其占则凶也。</p><h3 id="程传-17" tabindex="-1">程传 <a class="header-anchor" href="#程传-17" aria-label="Permalink to “程传”">​</a></h3><p>六居恒之极，在震之终。恒极则不常，震终则动极。以阴居上，非其安处，又阴柔不能坚固其守，皆不常之义也。故为“振恒”，以振为恒也。振者，动之速也，如振衣、如振书，抖擞运动之意。在上而其动无节，以此为恒，其凶宜矣。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰：夫静为躁君，安为动主，故安者上之所处也，静者可久之道也。处卦之上，居动之极，以此为恒，无施而得也。</p></li><li><p>王氏申子曰：振者，运动而无常也。居恒之终，处震之极。恒终则变而不能恒，震极则动而不能止，故有“振恒”之象。在上而动无恒，其凶宜矣。</p></li></ul><p>象曰：振恒在上，大无功也</p><h3 id="程传-18" tabindex="-1">程传 <a class="header-anchor" href="#程传-18" aria-label="Permalink to “程传”">​</a></h3><p>居上之道，必有恒德乃能有功。若躁动不常，岂能有所成乎？居上而不恒，其凶甚矣。象又言其不能有所成立，故曰“大无功也”。</p><h3 id="集说-15" tabindex="-1">集说 <a class="header-anchor" href="#集说-15" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏安石曰：终乎动，以动为恒者也。以动为恒而在物上，其害大矣。</p></li><li><p>王氏申子曰：此所谓“天下本无事，庸人自扰之”。其好功生事之过乎？故圣人折之曰“大无功”，言振扰于守恒之时，决无所成也。</p></li></ul><p>总论</p><ul><li><p>丘氏富国曰：恒，中道也。中则能恒，不中则不恒矣。恒卦六爻无上下相应之义，惟以二体而取中焉，则恒之义见矣。初在下体之下，四在上体之下，皆未及乎恒者，故泥常而不知变，是以初“浚恒”，四“田无禽”也。三在下体之上，上在上体之上，皆已过乎恒者，故好变而不知常，是以三“不恒”，而上“振恒”也。惟二五得上下体之中，知恒之义者。而五位刚爻柔，以柔中为恒，故不能制义，而但为妇人之吉；二位柔爻刚，以刚中为恒，而居位不当，亦不能尽守常之义，故特言“悔亡”而已。恒之道，岂易言哉！</p></li><li><p>李氏舜臣曰：咸、恒二卦，其彖甚善，而六爻之义鲜有全吉者。盖以爻而配六位，则阴阳得失、承乘逆顺之理，又各不相同故也。</p></li></ul>',125)])])}const m=e(h,[["render",p]]);export{b as __pageData,m as default};
